function tick(now){frame=0;if(!enabled||!shown||document.hidden)return;if(hitTest){hitTest=false;if(!context(document.elementFromPoint(x,y)))return;aim()}const dt=Math.min(40,last?now-last:16);last=now;const smooth=1-Math.exp(-dt/9);px+=(tx-px)*smooth;py+=(ty-py)*smooth;dot.style.transform=`translate3d(${px.toFixed(2)}px,${py.toFixed(2)}px,0)`;let moving=Math.abs(tx-px)+Math.abs(ty-py)>.04;
if(magnet){const m=magnet,ease=1-Math.exp(-dt/45);m.x+=(m.tx-m.x)*ease;m.y+=(m.ty-m.y)*ease;m.el.style.translate=`${m.x.toFixed(2)}px ${m.y.toFixed(2)}px`;moving=moving||Math.abs(m.tx-m.x)+Math.abs(m.ty-m.y)>.02}if(moving)frame=requestAnimationFrame(tick);else last=0}
